head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > ondatadragstart]<br/>Drag 로 Body 영역의 데이터 이동을 시작할 때 발생합니다.",
    "validation" : [
        "dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성 중 하나 이상 true 여야 이벤트가 발생합니다.",
        "rowIndex : Drag 가 시작된 데이터의 Row 인덱스값이 전달됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - target1 에 dataDragDropSelf=true 고정 -> Row Drag 시작 시 ondatadragstart 발생
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind1 !== 'undefined') {
        $p.data.remove("dlt_bind1");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] target1 에 dataDragDropSelf=true(자체 Drag&Drop 허용).\n[절차] target1 의 Row 를 Drag 하여 이동 시작 -> ondatadragstart 발생(rowIndex 출력)."', '', 'label1');

    // properties 고정 : dataDragDropSelf=true (dataDragDrop* 중 하나 이상 true -> ondatadragstart 발생 조건 충족)
    let properties = {
        dataList: "data:dlt_bind1",
        dataDragDropSelf: "true"
    };

    let cList = $c.gcm.createCList(properties);

    // 이벤트 핸들러 부착 : target1 에 ondatadragstart
    let eList = $c.gcm.createEList(["ondatadragstart"], "target1");

    // dataList 생성 (기본 4행) + target1 생성 (기본 4컬럼)
    $c.gcm.createBasicDataList('', '', 'dlt_bind1');
    await $c.gcm.createBasicGridView(cList, eList, 'target1');
}



// ondatadragstart : dataDragDropSelf 모드에서 Drag 시작 시 발생 (검증 대상)
//  - rowIndex : Drag 가 시작된 데이터의 Row 인덱스
scwin.target1_ondatadragstart = function (rowIndex) {
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("ondatadragstart rowIndex : " + rowIndex);
};
